"use client";

import { useEffect, useId, useRef, useState, type FormEvent, type ReactNode } from "react";
import { Button } from "@/components/ui/button";
import { Field, Input, Select, Textarea } from "@/components/ui/field";
import { Surface } from "@/components/ui/surface";
import { Notice, StatusChip } from "@/components/ui/status";
import { websiteSalesOperationsCopy, websiteSalesTopicLabels } from "@/lib/website-sales-operations-copy";
import { formatSalesMinor, formatSalesPercent, parseSalesHundredths, salesHundredthsInput, salesLocalDateTime } from "@/lib/website-sales-operations-format";
import { markSalesOperationsCurrentRead, readSalesConversation, readSalesOperations, reconcileSalesOperations, salesOperationsPending, SalesOperationsBrowserError, subscribeSalesOperationsPending, writeSalesOperations, type SalesOperationsArea } from "@/lib/website-sales-operations-client";
import { websiteSalesOperationsContract, type SalesOperationsCommand, type SalesOperationsOperation, type SalesOperationsRead, type SalesPolicy } from "@/lib/website-sales-operations-types";
import { websiteSalesConversationContract, websiteSalesConversationTopics, type SalesConversationCommand, type SalesConversationOperation, type SalesConversationRead, type SalesConversationScope } from "@/lib/website-sales-conversation-types";

type Props = SalesConversationScope & { workspaceId: string; actorId: string; language: string; blocked?: boolean; onStateChanged?: () => void };
type Copy = ReturnType<typeof websiteSalesOperationsCopy>;
type Errors = Record<string, string>;
type FormContext = { id: string; errors: Errors; copy: Copy };
type OperationCall = (operation: SalesOperationsOperation, payload: Record<string, unknown>, version: number) => Promise<boolean>;
type ConversationCall = (operation: SalesConversationOperation, payload: Record<string, unknown>) => Promise<boolean>;
const control = "min-h-11 w-full min-w-0 scroll-mt-20";
const areas: SalesOperationsArea[] = ["autonomy", "conversation"];
const stages = ["DIAGNOSIS", "CONCEPT", "CONCEPT_ACCEPTANCE", "DEMO", "CONVERSATION"] as const;
const object = (value: unknown): Record<string, unknown> => value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
const date = (value: string, language: string) => new Date(value).toLocaleString(language === "de" ? "de-AT" : "en-IE");
const defaultEnd = () => new Date(Date.now() + 86400000).toISOString();
function activePolicies(data: SalesOperationsRead, kind: SalesPolicy["kind"]) {
  const current = new Map<string, SalesPolicy>();
  for (const policy of data.policies) if (policy.kind === kind && policy.active && (!current.has(policy.policyGroupId) || current.get(policy.policyGroupId)!.version < policy.version)) current.set(policy.policyGroupId, policy);
  return [...current.values()];
}
class FormFieldError extends Error { constructor(readonly field: string) { super(field); } }
function number(values: FormData, name: string, minimum = 0, maximum = Number.MAX_SAFE_INTEGER) {
  const raw = String(values.get(name) ?? ""); if (!/^\d+$/.test(raw)) throw new FormFieldError(name);
  const value = Number(raw); if (!Number.isSafeInteger(value) || value < minimum || value > maximum) throw new FormFieldError(name); return value;
}
function hundredths(values: FormData, name: string, maximum = Number.MAX_SAFE_INTEGER) {
  try { const value = parseSalesHundredths(String(values.get(name) ?? "")); if (value > maximum) throw Error(); return value; } catch { throw new FormFieldError(name); }
}
function timestamp(values: FormData, name: string) { const value = new Date(String(values.get(name) ?? "")); if (!Number.isFinite(value.getTime())) throw new FormFieldError(name); return value.toISOString(); }
function CheckedForm({ name, title, copy, disabled, onSubmit, children }: { name: string; title?: string; copy: Copy; disabled: boolean; onSubmit: (values: FormData) => Promise<boolean>; children: (context: FormContext) => ReactNode }) {
  const id = useId().replace(/:/g, ""), summary = useRef<HTMLDivElement>(null), [errors, setErrors] = useState<Errors>({});
  useEffect(() => { if (Object.keys(errors).length) summary.current?.focus(); }, [errors]);
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (disabled) return;
    const form = event.currentTarget, invalid: Errors = {};
    for (const field of Array.from(form.elements)) if ((field instanceof HTMLInputElement || field instanceof HTMLTextAreaElement || field instanceof HTMLSelectElement) && !field.disabled && field.id && !field.validity.valid) invalid[field.id] = copy.required;
    setErrors(invalid); if (Object.keys(invalid).length) return;
    try { await onSubmit(new FormData(form)); } catch (error) { setErrors({ [error instanceof FormFieldError ? `${id}-${error.field}` : `${id}-summary`]: error instanceof FormFieldError ? copy.required : copy.denied }); }
  }
  return <form noValidate autoComplete="off" onSubmit={event => void submit(event)} className="space-y-5" data-testid={name}>
    {title ? <h3 className="text-lg font-semibold">{title}</h3> : null}
    {Object.keys(errors).length ? <div ref={summary} id={`${id}-summary`} tabIndex={-1} role="alert" className="scroll-mt-20 rounded-lg border border-red-300 bg-red-50 p-4 text-sm text-red-950"><h4 className="font-semibold">{copy.invalid}</h4><ul className="mt-2 list-disc pl-5">{Object.entries(errors).map(([field, error]) => <li key={field}><a className="underline" href={`#${field}`}>{error}</a></li>)}</ul></div> : null}
    <fieldset disabled={disabled} className="min-w-0 space-y-5">{children({ id, errors, copy })}</fieldset>
  </form>;
}
function FormInput({ context, name, label, value = "", type = "text", min, max, money = false, required = true }: { context: FormContext; name: string; label: string; value?: string | number; type?: string; min?: number; max?: number; money?: boolean; required?: boolean }) {
  const id = `${context.id}-${name}`, error = context.errors[id];
  return <Field htmlFor={id} label={label} required={required} error={error} errorId={`${id}-error`}><Input className={control} id={id} name={name} type={type} defaultValue={value} required={required} min={min} max={max} step={type === "number" ? 1 : undefined} maxLength={type === "text" ? 1000 : undefined} inputMode={money ? "decimal" : undefined} pattern={money ? "[0-9]+([,.][0-9]{1,2})?" : undefined} aria-invalid={!!error} aria-describedby={error ? `${id}-error` : undefined} /></Field>;
}
function FormSelect({ context, name, label, value = "", children, onChange }: { context: FormContext; name: string; label: string; value?: string; children: ReactNode; onChange?: (value: string) => void }) {
  const id = `${context.id}-${name}`, error = context.errors[id];
  return <Field htmlFor={id} label={label} required error={error} errorId={`${id}-error`}><Select className={control} id={id} name={name} defaultValue={value} required onChange={event => onChange?.(event.target.value)} aria-invalid={!!error} aria-describedby={error ? `${id}-error` : undefined}>{children}</Select></Field>;
}
function Confirmation({ context, name = "confirm", label }: { context: FormContext; name?: string; label: string }) {
  const id = `${context.id}-${name}`, error = context.errors[id];
  return <div><label className="flex min-h-11 items-start gap-3 text-sm leading-6"><input className="mt-1 size-5 shrink-0 accent-blue-700" type="checkbox" id={id} name={name} required aria-invalid={!!error} aria-describedby={error ? `${id}-error` : undefined} /><span>{label}</span></label>{error ? <p id={`${id}-error`} className="mt-1 text-sm text-red-700">{error}</p> : null}</div>;
}
function stageLabel(value: string, language: string) { const de: Record<string, string> = { DIAGNOSIS: "Diagnose", CONCEPT: "Konzept", CONCEPT_ACCEPTANCE: "Konzeptprüfung", DEMO: "Demo", CONVERSATION: "Gespräch" }; const en: Record<string, string> = { DIAGNOSIS: "Diagnosis", CONCEPT: "Concept", CONCEPT_ACCEPTANCE: "Concept review", DEMO: "Demo", CONVERSATION: "Conversation" }; return (language === "de" ? de : en)[value] ?? value; }

export function WebsiteSalesOperationsPanel(props: Props) { return <OperationsPanel key={`${props.actorId}:${props.workspaceId}:${props.projectId}:${props.companyId}:${props.locationId}`} {...props} />; }
function OperationsPanel({ workspaceId, actorId, language, blocked = false, onStateChanged, ...scope }: Props) {
  const copy = websiteSalesOperationsCopy(language), id = useId().replace(/:/g, ""), generation = useRef(0), tabs = useRef<(HTMLButtonElement | null)[]>([]);
  const scopeKey = JSON.stringify([workspaceId, scope]), [attempt, setAttempt] = useState(0), [busy, setBusy] = useState(false), [dirty, setDirty] = useState(false), [message, setMessage] = useState("");
  const [selectedTab, setSelectedTab] = useState(() => Math.max(0, ["portfolio", "pricing", "conversation", "outcomes"].indexOf(new URL(window.location.href).searchParams.get("salesTab") ?? ""))), [visited, setVisited] = useState(() => new Set([selectedTab])), [, rerender] = useState(0);
  const [loaded, setLoaded] = useState<{ key: string; operations: SalesOperationsRead | null; conversation: SalesConversationRead | null; failed: boolean; readAt: number } | null>(null);
  const data = loaded?.key === scopeKey ? loaded : null, recoveries = areas.map(area => ({ area, pending: salesOperationsPending(area, workspaceId, actorId) })).filter(item => item.pending);
  const locked = blocked || busy || recoveries.length > 0;
  useEffect(() => subscribeSalesOperationsPending(() => rerender(value => value + 1)), []);
  useEffect(() => {
    const controller = new AbortController(), ticket = ++generation.current, [, selectedScope] = JSON.parse(scopeKey) as [string, SalesConversationScope];
    const references = areas.map(area => { const pending = salesOperationsPending(area, workspaceId, actorId); return { area, reference: pending && !pending.damaged && pending.state === "UNKNOWN" ? { idempotencyKey: pending.command.idempotencyKey, correlationId: pending.command.correlationId } : null }; });
    void Promise.allSettled([readSalesOperations(workspaceId, selectedScope, controller.signal), readSalesConversation(workspaceId, selectedScope, controller.signal)]).then(([operations, conversation]) => {
      if (controller.signal.aborted || generation.current !== ticket) return;
      setLoaded({ key: scopeKey, operations: operations.status === "fulfilled" ? operations.value : null, conversation: conversation.status === "fulfilled" ? conversation.value : null, failed: operations.status === "rejected" || conversation.status === "rejected", readAt: Date.now() });
      for (const { area, reference } of references) if (reference && (area === "autonomy" ? operations.status : conversation.status) === "fulfilled") markSalesOperationsCurrentRead(area, workspaceId, actorId, reference, selectedScope);
    });
    return () => { controller.abort(); generation.current = ticket + 1; };
  }, [workspaceId, actorId, scopeKey, attempt]);
  useEffect(() => { const handler = (event: BeforeUnloadEvent) => { if (dirty || areas.some(area => salesOperationsPending(area, workspaceId, actorId))) { event.preventDefault(); event.returnValue = ""; } }; window.addEventListener("beforeunload", handler); return () => window.removeEventListener("beforeunload", handler); }, [dirty, workspaceId, actorId]);
  async function execute(area: SalesOperationsArea, command: SalesOperationsCommand | SalesConversationCommand, retry = false) {
    if (!retry && locked) return false;
    const ticket = generation.current; setBusy(true); setMessage("");
    try { await writeSalesOperations(area, workspaceId, actorId, command, retry); if (ticket === generation.current) { setMessage(copy.saved); setDirty(false); setAttempt(value => value + 1); onStateChanged?.(); } return true; }
    catch (error) { if (ticket === generation.current) setMessage(error instanceof SalesOperationsBrowserError && error.outcome === "DENIED" ? copy.denied : copy.unknown); return false; }
    finally { if (ticket === generation.current) setBusy(false); }
  }
  const operation: OperationCall = (operation, payload, expectedVersion) => execute("autonomy", { contractVersion: websiteSalesOperationsContract, operation, ...scope, expectedVersion, idempotencyKey: crypto.randomUUID(), correlationId: crypto.randomUUID(), payload });
  const conversation: ConversationCall = (operation, payload) => { if (!data?.conversation) return Promise.resolve(false); return execute("conversation", { contractVersion: websiteSalesConversationContract, operation, ...scope,
    expectedConversationVersion: data.conversation.conversation?.version ?? 0, expectedWorkflowVersion: data.conversation.workflow.version, idempotencyKey: crypto.randomUUID(), correlationId: crypto.randomUUID(), payload }); };
  async function refreshOriginal(area: SalesOperationsArea) {
    const original = salesOperationsPending(area, workspaceId, actorId); if (!original || original.damaged) return;
    const reference = { idempotencyKey: original.command.idempotencyKey, correlationId: original.command.correlationId }, originalScope = { projectId: original.command.projectId, companyId: original.command.companyId, locationId: original.command.locationId }, ticket = generation.current;
    setBusy(true);
    try { if (area === "autonomy") await readSalesOperations(workspaceId, originalScope); else await readSalesConversation(workspaceId, originalScope); if (ticket === generation.current) { markSalesOperationsCurrentRead(area, workspaceId, actorId, reference, originalScope); setAttempt(value => value + 1); } }
    catch { if (ticket === generation.current) setMessage(copy.failed); } finally { if (ticket === generation.current) setBusy(false); }
  }
  async function reconcile(area: SalesOperationsArea) { const ticket = generation.current; setBusy(true); try { const result = await reconcileSalesOperations(area, workspaceId, actorId); if (ticket === generation.current) { setMessage(result === "COMMITTED" ? copy.saved : copy.notFound); setAttempt(value => value + 1); onStateChanged?.(); } } catch { if (ticket === generation.current) setMessage(copy.unknown); } finally { if (ticket === generation.current) setBusy(false); } }
  function selectTab(index: number) { setVisited(value => new Set([...value, index])); setSelectedTab(index); const url = new URL(window.location.href); url.searchParams.set("salesTab", panels[index]); window.history.replaceState(window.history.state, "", url); }
  const panels = ["portfolio", "pricing", "conversation", "outcomes"];
  return <section className="min-w-0 space-y-5" data-testid="website-sales-operations" data-website-sales-operations aria-labelledby={`${id}-title`} onChangeCapture={() => setDirty(true)}>
    <div className="flex flex-wrap items-start justify-between gap-4"><div><h2 className="text-2xl font-semibold tracking-tight text-slate-950" id={`${id}-title`}>{copy.title}</h2><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-600">{copy.intro}</p></div><Button variant="secondary" disabled={busy} onClick={() => setAttempt(value => value + 1)}>{copy.refresh}</Button></div>
    {language !== "de" && language !== "en" ? <p className="text-sm text-slate-600" lang="en">English is shown for these Sales tools.</p> : null}
    <div className="flex flex-wrap items-center gap-3"><StatusChip>{copy.internal}</StatusChip>{data?.operations && !data.operations.canWrite ? <StatusChip>{copy.readOnly}</StatusChip> : null}</div>
    {message ? <p className="text-sm text-slate-700" role="status">{message}</p> : null}
    {recoveries.map(({ area, pending }) => <Notice key={area} tone="warning"><p>{pending?.damaged ? copy.damaged : copy.unknown}</p>{pending && !pending.damaged ? <div className="mt-3 flex flex-wrap gap-3"><Button variant="secondary" disabled={busy} onClick={() => void refreshOriginal(area)}>{copy.refresh}</Button><Button variant="secondary" disabled={busy || !pending.currentRead} onClick={() => void reconcile(area)}>{copy.reconcile}</Button>{pending.retryAllowed ? <Button disabled={busy} onClick={() => void execute(area, pending.command, true)}>{copy.retry}</Button> : null}</div> : null}</Notice>)}
    {data?.failed ? <Notice tone="danger">{copy.failed}</Notice> : null}{!data ? <p role="status">{copy.loading}</p> : null}
    <div role="tablist" aria-label={copy.title} className="flex flex-wrap gap-2 border-b border-slate-200 pb-3">{copy.tabs.map((name, index) => <button key={name} ref={element => { tabs.current[index] = element; }} type="button" role="tab" aria-selected={selectedTab === index} aria-controls={`${id}-${panels[index]}`} id={`${id}-tab-${index}`} tabIndex={selectedTab === index ? 0 : -1} className={`min-h-11 rounded-lg border px-4 py-2 text-sm font-medium focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-700 ${selectedTab === index ? "border-blue-700 bg-blue-50 text-blue-900" : "border-slate-200 bg-white text-slate-700"}`} onClick={() => selectTab(index)} onKeyDown={event => { const next = event.key === "ArrowRight" ? (index + 1) % 4 : event.key === "ArrowLeft" ? (index + 3) % 4 : event.key === "Home" ? 0 : event.key === "End" ? 3 : null; if (next !== null) { event.preventDefault(); selectTab(next); tabs.current[next]?.focus(); } }}>{name}</button>)}</div>
    {panels.map((panel, index) => <div key={panel} role="tabpanel" id={`${id}-${panel}`} aria-labelledby={`${id}-tab-${index}`} hidden={selectedTab !== index} data-testid={`website-operations-${panel}`} className="min-w-0 space-y-5">
      {visited.has(index) && data ? index === 0 && data.operations ? <PortfolioPanel data={data.operations} dialogue={data.conversation} scope={scope} language={language} copy={copy} locked={locked || !data.operations.canWrite} operation={operation} readAt={data.readAt} />
        : index === 1 && data.operations ? <PricingPanel data={data.operations} dialogue={data.conversation} language={language} copy={copy} locked={locked || !data.operations.canWrite} operation={operation} />
          : index === 2 && data.conversation ? <ConversationPanel data={data.conversation} language={language} copy={copy} locked={locked || !data.conversation.canWrite} conversation={conversation} />
            : index === 3 && data.operations ? <OutcomesPanel data={data.operations} language={language} copy={copy} locked={locked || !data.operations.canWrite} operation={operation} /> : null : null}
    </div>)}
    {dirty ? <p className="text-xs text-slate-500">{copy.dirty}</p> : null}
  </section>;
}

function ConversationPanel({ data, language, copy, locked, conversation }: { data: SalesConversationRead; language: string; copy: Copy; locked: boolean; conversation: ConversationCall }) {
  const [messageId, setMessageId] = useState(""), [answerLanguage, setAnswerLanguage] = useState<"de" | "en">(language === "de" ? "de" : "en");
  const source = data.sources.find(value => value.messageId === messageId), labels = websiteSalesTopicLabels(language), topicLabel = (code: string) => labels[websiteSalesConversationTopics.indexOf(code as typeof websiteSalesConversationTopics[number])] ?? code;
  const stopped = data.conversation?.status === "STOPPED", currentDraft = data.turns.find(turn => turn.current && turn.draft)?.draft;
  return <>
    <Surface className="space-y-5 p-5 sm:p-6"><h3 className="text-lg font-semibold">{copy.conversationTitle}</h3><p className="max-w-3xl text-sm leading-6 text-slate-600">{copy.conversationHint}</p>
      {data.sources.length ? <>
        <Field htmlFor="website-conversation-message" label={copy.message}><Select className={control} id="website-conversation-message" value={messageId} onChange={event => setMessageId(event.target.value)} disabled={locked}><option value="">{copy.choose}</option>{data.sources.map(row => <option key={row.messageId} value={row.messageId}>{date(row.receivedAt, language)} · {topicLabel(row.topicCode)}</option>)}</Select></Field>
        <Field htmlFor="website-conversation-language" label={copy.language}><Select className={control} id="website-conversation-language" value={answerLanguage} onChange={event => setAnswerLanguage(event.target.value as "de" | "en")} disabled={locked}><option value="de">Deutsch</option><option value="en">English</option></Select></Field>
        {source ? <div className="space-y-4"><StatusChip tone={source.authorized ? "success" : "neutral"}>{source.authorized ? copy.authorized : copy.notAuthorized}</StatusChip>
          {source.canAuthorize ? <CheckedForm key={`${source.messageId}:${source.authorized}`} name="website-conversation-permission" copy={copy} disabled={locked || stopped && !source.authorized} onSubmit={() => conversation("authorize_topic_extraction", { canonicalMessageId: source.messageId, allow: true })}>{context => <><Confirmation context={context} label={copy.permission} /><Button type="submit" disabled={source.authorized}>{copy.allow}</Button></>}</CheckedForm> : null}
          {source.canAuthorize && source.authorized ? <Button variant="secondary" disabled={locked} onClick={() => void conversation("authorize_topic_extraction", { canonicalMessageId: source.messageId, allow: false })}>{copy.revoke}</Button> : null}
          <Button disabled={locked || !source.authorized || stopped && source.topicCode !== "OPT_OUT"} onClick={() => void conversation("advance_conversation", { canonicalMessageId: source.messageId, language: answerLanguage })}>{copy.advance}</Button>
        </div> : null}
      </> : <p className="text-sm text-slate-600">{copy.noMessages}</p>}
    </Surface>
    <div className="grid min-w-0 gap-5 xl:grid-cols-2"><Surface className="space-y-4 p-5 sm:p-6"><CheckedForm name="website-conversation-manual" title={copy.manual} copy={copy} disabled={locked || stopped} onSubmit={values => conversation("record_topic", { topicCode: String(values.get("topic")), language: answerLanguage })}>{context => <><p className="text-sm leading-6 text-slate-600">{copy.manualHint}</p><FormSelect context={context} name="topic" label={copy.topic}>{<><option value="">{copy.choose}</option>{websiteSalesConversationTopics.filter(code => code !== "OPT_OUT").map(code => <option value={code} key={code}>{topicLabel(code)}</option>)}</>}</FormSelect><Button type="submit">{copy.recordTopic}</Button></>}</CheckedForm></Surface>
      <Surface className="space-y-4 p-5 sm:p-6"><CheckedForm name="website-conversation-fact" title={copy.facts} copy={copy} disabled={locked || stopped || !data.canApproveFacts} onSubmit={values => conversation("record_answer_fact", { topicCode: String(values.get("topic")), text: String(values.get("text")).trim(), sourceReference: String(values.get("reference")).trim(), validUntil: timestamp(values, "until"), classification: String(values.get("classification")) })}>{context => <>{!data.canApproveFacts ? <p className="text-sm text-slate-600">{copy.ownerOnly}</p> : null}<FormSelect context={context} name="topic" label={copy.topic}><option value="">{copy.choose}</option>{websiteSalesConversationTopics.filter(code => !["PRICE", "DISCOUNT", "OBJECTION_PRICE", "OPT_OUT", "UNKNOWN", "LEGAL_OR_CONTRACT", "ACCEPTANCE"].includes(code)).map(code => <option value={code} key={code}>{topicLabel(code)}</option>)}</FormSelect>
        <Field htmlFor={`${context.id}-text`} label={copy.factText} required error={context.errors[`${context.id}-text`]} errorId={`${context.id}-text-error`}><Textarea className={control} id={`${context.id}-text`} name="text" rows={4} required maxLength={1000} aria-invalid={!!context.errors[`${context.id}-text`]} aria-describedby={context.errors[`${context.id}-text`] ? `${context.id}-text-error` : undefined} /></Field>
        <FormInput context={context} name="reference" label={copy.factSource} /><FormInput context={context} name="until" label={copy.until} type="datetime-local" value={salesLocalDateTime(defaultEnd())} /><FormSelect context={context} name="classification" label={copy.factClass} value="APPROVED_SALES"><option value="PUBLIC_BUSINESS">{copy.publicBusiness}</option><option value="APPROVED_SALES">{copy.approvedSales}</option></FormSelect><Confirmation context={context} label={copy.factApprove} /><Button type="submit">{copy.saveFact}</Button></>}</CheckedForm></Surface></div>
    <Surface className="space-y-4 p-5 sm:p-6" data-testid="website-conversation-draft"><h3 className="text-lg font-semibold">{copy.draft}</h3>{currentDraft ? <><StatusChip tone={currentDraft.status === "DRAFT_READY" ? "info" : "warning"}>{currentDraft.status === "WAITING_FOR_FACTS" ? copy.needsFacts : currentDraft.status === "HUMAN_REVIEW_REQUIRED" ? copy.humanReview : currentDraft.status === "STOPPED" ? copy.stopTitle : copy.draft}</StatusChip>{currentDraft.body ? <div className="max-w-3xl whitespace-pre-wrap text-sm leading-7 text-slate-800">{currentDraft.body}</div> : null}{currentDraft.requiresOfferApproval ? <Notice tone="warning">{copy.approvalNeeded}</Notice> : null}<p className="text-xs leading-5 text-slate-500">{copy.draftInternal}</p></> : <p className="text-sm text-slate-600">{copy.noDraft}</p>}
      {data.turns.filter(turn => turn.kind === "TOPIC_RECORDED" && turn.current).length ? <CheckedForm name="website-conversation-prepare" copy={copy} disabled={locked || stopped} onSubmit={values => conversation("draft_answer", { topicTurnId: String(values.get("topicTurn")), expectedFactsDigest: data.factsDigest })}>{context => <><FormSelect context={context} name="topicTurn" label={copy.topicTurn}><option value="">{copy.choose}</option>{data.turns.filter(turn => turn.kind === "TOPIC_RECORDED" && turn.current).map(turn => <option key={turn.id} value={turn.id}>{topicLabel(turn.topicCode)} · {date(turn.createdAt, language)}</option>)}</FormSelect><Button type="submit">{copy.draftAnswer}</Button></>}</CheckedForm> : null}
    </Surface>
    <Surface className="space-y-4 p-5 sm:p-6"><h3 className="text-lg font-semibold">{copy.history}</h3><ol className="space-y-4">{[...data.turns].reverse().map(turn => <li key={turn.id} className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 pb-3 text-sm"><span>{topicLabel(turn.topicCode)} · <time dateTime={turn.createdAt}>{date(turn.createdAt, language)}</time></span>{!turn.current ? <StatusChip>{copy.historical}</StatusChip> : <StatusChip tone="info">{turn.draft ? copy.draft : copy.topicTurn}</StatusChip>}</li>)}</ol></Surface>
    <details className="rounded-xl border border-slate-200 bg-white p-5"><summary className="min-h-11 cursor-pointer font-semibold">{copy.stopTitle}</summary><CheckedForm name="website-conversation-stop" copy={copy} disabled={locked} onSubmit={values => conversation("stop_conversation", { reason: String(values.get("reason")) })}>{context => <><FormSelect context={context} name="reason" label={copy.stopReason} value="OPERATOR_STOP"><option value="OPERATOR_STOP">{copy.operatorStop}</option><option value="OPT_OUT">{copy.optOut}</option><option value="NO_FIT">{copy.noFit}</option><option value="UNKNOWN_DELIVERY">{copy.unknownDelivery}</option></FormSelect><Confirmation context={context} label={copy.stopConfirm} /><Button type="submit" variant="secondary">{copy.stop}</Button></>}</CheckedForm></details>
  </>;
}

type OperationsPanelProps = { data: SalesOperationsRead; language: string; copy: Copy; locked: boolean; operation: OperationCall; readAt?: number };
