  const portfolio = data.portfolio, rule = data.policies.find(value => value.id === portfolio?.policyId), settings = object(rule?.settings), policy = object(rule?.policy), weights = object(policy.weights);
  const estimates = Array.isArray(settings.stageEstimates) ? settings.stageEstimates.map(object) : [], pricing = activePolicies(data, "PRICING"), workflow = object(data.workflow), ownerLocked = locked || !data.canApprovePolicies;
